const D = { energy: .6, density: .5, scale: 1, speed: 1, quake: .5, hue: 32, x: .5, y: .5, style: 'smoked', act: 'watch', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const TAU = Math.PI * 2;
const clp = (v, a, b) => Math.max(a, Math.min(b, v));
const md = (a, n) => ((a % n) + n) % n;
// integer hash — finalize with >>> (>> sign-extends and caps the hash at 0.5)
function h2(ix, iy) { let h = (ix * 374761393 + iy * 668265263 + (P.seed | 0) * 1442695041) | 0; h = Math.imul(h ^ (h >>> 13), 1274126177); return ((h ^ (h >>> 16)) >>> 0) / 4294967295; }
function h1(i) { return h2(i | 0, 0x2f1b); }
function vn1(x) { const ix = Math.floor(x), fx = x - ix, ux = fx*fx*(3-2*fx); const a = h2(ix, 77), b = h2(ix+1, 77); return a + (b-a)*ux; }

const en = clp(P.energy, 0, 1), dens = clp(P.density, 0, 1), qk = clp(P.quake, 0, 1);
const W = width, H = height, u = Math.min(W, H);
const hs = P.hue - 32;

const ST = {
  smoked:   { pap:[26,42,13],  ink:[35,6,99],   rule:[16,60,40], chas:[30,10,31], lbl:[32,16,72], dark:1 },
  thermal:  { pap:[36,26,56],  ink:[28,30,10],  rule:[6,74,48],  chas:[32,14,36], lbl:[28,30,26], dark:0 },
  blueprint:{ pap:[212,58,30], ink:[200,6,97],  rule:[200,30,62],chas:[214,40,20],lbl:[200,20,80],dark:1 },
  envelope: { pap:[220,30,11], ink:[186,72,92], rule:[220,26,34],chas:[220,16,26],lbl:[200,14,70],dark:1 }
};
const st = ST[P.style] || ST.smoked;
const PAH = md(st.pap[0] + hs, 360), INH = md(st.ink[0] + hs, 360), RUH = md(st.rule[0] + hs, 360), CHH = md(st.chas[0] + hs, 360), LBH = md(st.lbl[0] + hs, 360);

// ---- act dramaturgy ----
let evRate = .35 + dens * .9, ampMul = 1, micro = 1;
if (P.act === 'swarm') { evRate = 1.6 + dens * 3.4; ampMul = .72; }
else if (P.act === 'teleseism') { evRate = .12 + dens * .3; ampMul = 2.6; micro = .55; }

const NL = 20, PW = 1100, LH = 31, PH = NL * LH;
const REV = 5.7 / clp(0.25 + P.speed * .75, .1, 3);   // irrational rev period, never near the 8 s gate window

// ---- the trace: a pure function of pen position p (in revolutions) ----
function sig(p) {
  const gx = p * PW;
  let v = micro * (0.52 * (vn1(gx * 0.055 + 3.1) - .5) + 0.30 * (vn1(gx * 0.21 + 41.7) - .5) + 0.17 * (vn1(gx * 0.85 + 77.3) - .5));
  v *= 0.85 + 0.42 * Math.sin(p * 0.63 + 1.1);                 // diurnal noise breathing
  const spacing = 1.15 / Math.max(evRate, .04);
  const i0 = Math.floor((p - spacing * 2.2) / spacing), i1 = Math.floor(p / spacing);
  for (let i = i0; i <= i1; i++) {
    const p0 = i * spacing + h1(i * 5 + 1) * spacing * .9;
    const dp = p - p0;
    if (dp <= 0) continue;
    const mag = (0.25 + Math.pow(h1(i * 5 + 2), 3.1) * 5.4) * qk * ampMul;
    const tauP = 0.055 + h1(i * 5 + 3) * 0.16;
    if (dp > tauP * 9) continue;
    const f = 90 + h1(i * 5 + 4) * 260;
    const pEnv = Math.exp(-dp / (tauP * .5));
    v += mag * .34 * pEnv * Math.sin(dp * f * 2.3);            // P arrival
    const ds = dp - tauP * .55;                                 // S arrival, bigger, longer coda
    if (ds > 0) {
      const sEnv = Math.exp(-ds / tauP) * (1 - Math.exp(-ds * 60));
      v += mag * sEnv * (Math.sin(ds * f) * .7 + (vn1(ds * f * 3.3 + i) - .5) * 1.5);
    }
  }
  return v;
}

// ---- paper buffer (unrolled): x = circumference, y = line index ----
const key = P.style + '|' + (P.seed | 0) + '|' + Math.round(P.hue) + '|' + P.act + '|' + qk.toFixed(2) + '|' + dens.toFixed(2);
const pNow = K.t / REV;

function paperBG(g, x0, w0) {   // repaint clean paper + rules over a band of the drum
  g.noStroke();
  g.fill(PAH, st.pap[1], st.pap[2]);
  g.rect(x0, 0, w0, PH);
  const nt = clp(Math.round(w0 * PH / 900), 6, 1200);   // tooth count follows the band area, not a constant
  g.fill(PAH, st.pap[1] * .7, st.pap[2] * (st.dark ? 1.9 : .72), 9);
  for (let i = 0; i < nt; i++) {   // paper / soot tooth
    const gx = x0 + h2(i * 3 + (x0 | 0), 5) * w0, gy = h2(i * 3 + 1 + (x0 | 0), 9) * PH;
    g.rect(gx, gy, 1.6, 1.6);
  }
  g.stroke(RUH, st.rule[1], st.rule[2], 46); g.strokeWeight(1);
  for (let l = 0; l < NL; l++) g.line(x0, l * LH + LH * .5, x0 + w0, l * LH + LH * .5);
  g.stroke(RUH, st.rule[1], st.rule[2], 26);
  for (let m = 0; m <= 4; m++) { const mx = Math.round((x0 + w0 * 0 + PW * m / 4)); if (mx >= x0 - 2 && mx <= x0 + w0 + 2) g.line(mx, 0, mx, PH); }
}
function drawTrace(g, line, u0, u1, pBase) {
  const yc = line * LH + LH * .5;
  if (P.style === 'envelope') {
    g.noStroke(); g.fill(INH, st.ink[1], st.ink[2], 76);
    for (let x = Math.floor(u0); x <= u1; x++) {
      const p = pBase + x / PW;
      let mx = 0;
      for (let k = 0; k < 3; k++) mx = Math.max(mx, Math.abs(sig(p + k * 0.00022)));
      const a = clp(mx, 0, 3.2) * LH * .46 * (0.5 + en);
      g.rect(x, yc - a, 1, a * 2);
    }
    return;
  }
  g.noFill(); g.stroke(INH, st.ink[1], st.ink[2], 92); g.strokeWeight(st.dark ? 1.05 : 1.15);
  g.beginShape();
  for (let x = Math.floor(u0); x <= u1; x++) {
    const p = pBase + x / PW;
    const a = sig(p) * LH * .62 * (0.45 + en * 1.1);
    g.vertex(x, yc + clp(a, -LH * 4.2, LH * 4.2));
  }
  g.endShape();
}

if (!S.paper || S.key !== key) {
  if (S.paper && S.paper.remove) S.paper.remove();
  const g = createGraphics(PW, PH); g.pixelDensity(1); g.colorMode(g.HSB, 360, 100, 100, 100);
  paperBG(g, 0, PW);
  // prefill the whole drum with the last NL revolutions so it is NEVER blank
  const rev0 = Math.floor(pNow);
  for (let j = rev0 - NL + 1; j <= rev0; j++) {
    const line = md(j, NL);
    const uEnd = (j === rev0) ? clp((pNow - rev0) * PW, 1, PW) : PW;
    drawTrace(g, line, 0, uEnd, j);
  }
  S.paper = g; S.key = key; S.pPrev = pNow;
}
const paper = S.paper;

// ---- advance the stylus: erase the band ahead, ink the band just passed ----
if (S.pPrev == null || pNow < S.pPrev || pNow - S.pPrev > 0.4) S.pPrev = pNow - 0.0006;   // tolerate t0 reset
if (pNow > S.pPrev) {
  const EW = PW * 0.045;
  const j0 = Math.floor(S.pPrev), j1 = Math.floor(pNow);
  if (j1 === j0) {
    const a = (S.pPrev - j0) * PW, b = (pNow - j0) * PW;
    paperBG(paper, b, Math.min(EW, PW - b));
    drawTrace(paper, md(j0, NL), a, b, j0);
  } else {                       // crossed the seam: finish the old line, start the new one
    const a = (S.pPrev - j0) * PW;
    drawTrace(paper, md(j0, NL), a, PW, j0);
    const b = (pNow - j1) * PW;
    paperBG(paper, 0, Math.min(EW + b, PW));
    drawTrace(paper, md(j1, NL), 0, Math.max(b, 1), j1);
  }
  S.pPrev = pNow;
}

// =================== composite: the drum, seen on a vertical axis ===================
const cx = P.x * W, cy = P.y * H;
const Rc = 0.40 * u * clp(P.scale, .3, 2.2), Hd = 0.74 * H * clp(P.scale, .3, 2.2);
const yTop = cy - Hd * .5;

// chassis / backboard — carries the frame luminance so the drum is never a dark hole.
// Both are cached: the room at canvas size, the board in local coords so it still
// follows P.scale / P.x / P.y live.
const rkey = W + 'x' + H + '|' + P.style + '|' + Math.round(P.hue) + '|' + (P.seed | 0);
if (!S.room || S.rkey !== rkey) {
  if (S.room && S.room.remove) S.room.remove();
  if (S.board && S.board.remove) S.board.remove();
  const r = createGraphics(W, H); r.pixelDensity(1); r.colorMode(r.HSB, 360, 100, 100, 100);
  r.noStroke(); r.background(CHH, st.chas[1], st.chas[2] * .62);
  for (let i = 0; i < 46; i++) { r.fill(CHH, st.chas[1], st.chas[2] * (.62 + .5 * (i / 46)), 40); r.rect(0, H * i / 46, W, H / 46 + 1); }
  S.room = r;
  const BX = 420, BY = 620;
  const b = createGraphics(BX, BY); b.pixelDensity(1); b.colorMode(b.HSB, 360, 100, 100, 100);
  b.noStroke(); b.background(CHH, st.chas[1] * .8, st.chas[2] * 1.16);
  for (let i = 0; i < 900; i++) {   // brushed grain, baked once
    b.fill(CHH, st.chas[1] * .6, st.chas[2] * (.8 + h2(i * 3 + 9, 5) * .9), 13);
    b.rect(h2(i * 3 + 8, 4) * BX, h2(i * 3 + 7, 3) * BY, 12 + h2(i * 3 + 10, 6) * 46, 1);
  }
  S.board = b; S.rkey = rkey;
}
noStroke();
image(S.room, 0, 0, W, H);
image(S.board, cx - Rc * 1.34, yTop - u * .05, Rc * 2.68, Hd + u * .10);

const rot = md(pNow, 1) * TAU;
const NS = 64, XN = 0.985;
const dc = drawingContext;
dc.save();
dc.beginPath(); dc.rect(cx - Rc * XN - 1, yTop - 1, Rc * XN * 2 + 2, Hd + 2); dc.clip();
for (let j = 0; j < NS; j++) {
  const xn0 = -XN + 2 * XN * j / NS, xn1 = -XN + 2 * XN * (j + 1) / NS;
  const th0 = Math.asin(xn0) + rot, th1 = Math.asin(xn1) + rot;
  const sx0 = cx + Rc * xn0, sw = Rc * (xn1 - xn0);
  let u0 = md(th0 / TAU * PW, PW);
  const du = (th1 - th0) / TAU * PW;
  if (du <= 0.02) continue;
  if (u0 + du <= PW) image(paper, u0, 0, du, PH, sx0, yTop, sw, Hd);
  else {                              // slice straddles the paper seam: draw it in two parts
    const d1 = PW - u0, f = d1 / du;
    image(paper, u0, 0, d1, PH, sx0, yTop, sw * f, Hd);
    image(paper, 0, 0, du - d1, PH, sx0 + sw * f, yTop, sw * (1 - f), Hd);
  }
}
// cylindrical shading: limb darkening + a specular band that drifts on its own slow rate
const lit = 0.30 * Math.sin(K.t * 0.071) - 0.18;
noStroke();
for (let j = 0; j < NS; j++) {
  const xn = -XN + 2 * XN * (j + .5) / NS, sx0 = cx - Rc * XN + (2 * Rc * XN) * j / NS, sw = 2 * Rc * XN / NS + 1;
  const nz = Math.sqrt(Math.max(0, 1 - xn * xn));
  const lam = clp(nz * Math.cos(Math.asin(xn) - lit), 0, 1);
  fill(0, 0, 0, clp(64 * (1 - Math.pow(lam, .75)), 0, 78));
  rect(sx0, yTop, sw, Hd);
}
blendMode(ADD);
for (let j = 0; j < NS; j++) {
  const xn = -XN + 2 * XN * (j + .5) / NS, sx0 = cx - Rc * XN + (2 * Rc * XN) * j / NS, sw = 2 * Rc * XN / NS + 1;
  const spec = Math.pow(clp(1 - Math.abs(Math.asin(xn) - lit) / .55, 0, 1), 2.4);
  if (spec > 0.004) { fill(0, 0, 100, 16 * spec); rect(sx0, yTop, sw, Hd); }
}
blendMode(BLEND);
dc.restore();

// drum ends (the cylinder read) + spindle
noStroke();
fill(CHH, st.chas[1] * .7, st.chas[2] * 1.5); ellipse(cx, yTop, Rc * 2 * XN, Rc * .30);
fill(CHH, st.chas[1] * .9, st.chas[2] * .58); ellipse(cx, yTop + Hd, Rc * 2 * XN, Rc * .30);
noFill(); stroke(0, 0, 0, 46); strokeWeight(2); ellipse(cx, yTop + Hd, Rc * 2 * XN, Rc * .30);
fill(CHH, st.chas[1] * .5, st.chas[2] * 1.8); noStroke();
rect(cx - u * .008, yTop - u * .055, u * .016, u * .06);
rect(cx - u * .008, yTop + Hd - u * .004, u * .016, u * .06);

// hour labels + the time gutter beside the drum
textFont('Courier New'); textSize(clp(u * .0105, 6, 19)); textAlign(RIGHT, CENTER);
const curLine = md(Math.floor(pNow), NL);
for (let l = 0; l < NL; l++) {
  const yy = yTop + (l + .5) / NL * Hd;
  const age = md(curLine - l, NL);
  noStroke(); fill(LBH, st.lbl[1], st.lbl[2], l === curLine ? 96 : 44);
  const hh = md(Math.floor(pNow) - age, 24);
  text(String(hh).padStart(2, '0') + ':00', cx - Rc * 1.40, yy);
  if (l === curLine) { fill(md(st.rule[0] + hs, 360), 80, 90, 90); ellipse(cx - Rc * 1.36, yy, u * .006); }
}

// the stylus: arm + pen, riding the current line, translating down the drum
const penY = yTop + (curLine + .5) / NL * Hd;
stroke(CHH, st.chas[1] * .4, st.chas[2] * 2.1, 92); strokeWeight(u * .0075);
line(cx + Rc * 1.30, penY - u * .012, cx + Rc * .10, penY);
stroke(CHH, st.chas[1] * .5, st.chas[2] * 1.3, 80); strokeWeight(u * .003);
line(cx + Rc * 1.30, penY - u * .012, cx + Rc * .55, penY - u * .006);
noStroke(); fill(md(st.rule[0] + hs, 360), 74, 88, 96);
ellipse(cx + u * .004, penY, u * .010);
fill(CHH, st.chas[1] * .3, st.chas[2] * 2.3); rect(cx + Rc * 1.28, penY - u * .03, u * .022, u * .048, 2);

// placard
noStroke(); fill(LBH, st.lbl[1], st.lbl[2], 88); textAlign(LEFT, TOP); textSize(clp(u * .016, 8, 30));
text('HELICORDER  ·  STA GKN  ·  BHZ', u * .034, u * .030);
textSize(clp(u * .0105, 6, 19)); fill(LBH, st.lbl[1], st.lbl[2] * .82, 66);
text('GAIN ' + (en * 40 + 8).toFixed(0) + ' dB   ' + (REV * 60 / 3600).toFixed(3) + ' h/rev   ' + NL + ' LINES', u * .034, u * .052);
textAlign(RIGHT, TOP); fill(LBH, st.lbl[1], st.lbl[2] * .82, 66);
text(P.act.toUpperCase() + '   REV ' + String(Math.floor(pNow) % 10000).padStart(4, '0'), W - u * .034, u * .030);

blendMode(BLEND);
dc.shadowBlur = 0;
if (P.alpha < 100) { noStroke(); fill(CHH, st.chas[1], st.chas[2] * .62, 100 - clp(P.alpha, 0, 100)); rect(0, 0, W, H); }
